      "completed_scope": "Visible cabinet divisions, recessed panels, glazed door frames, handles, and base trim make the furniture groups recognizable while preserving their established proportions."
    },
    {
      "stage_id": 5,
      "title": "Appearance and global check",
      "targets": [
        "wood materials",
        "glass appearance",
        "lighting balance",
        "scene-wide verification"
      ],
      "completed_scope": "Wood tones and surface variation distinguish the countertop, cabinetry, and floor; a final render checks framing, visibility, contacts, and tonal readability across the completed scene, with obscured details recorded as uncertain."
    }
  ]
}

